<?php
namespace Tests\Feature;
use App\Contracts\{FaceProvider,ProtectedMediaStorage};use App\Jobs\{ExecuteProviderDeletion,IndexFaceAsset,SearchFaces};use App\Models\{BiometricConsent,BiometricReport,FaceMatchResult,FaceSearchSubject,Group,MediaAsset,MediaVariant,Photo,ProviderDeletionOperation,User};use App\Services\Face\{FaceRecognitionManager,FakeFaceProvider,RekognitionFaceProvider};use Aws\MockHandler;use Aws\Rekognition\RekognitionClient;use Aws\Result;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{Hash,Log,Queue,Storage};use Illuminate\Support\Str;use Mockery;use RuntimeException;use Tests\TestCase;
class BiometricComplianceTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();config(['face.provider'=>'fake','face.threshold'=>95,'face.manual_review'=>false,'face.minor_processing_enabled'=>false,'media.disk'=>'private_local','queue.default'=>'sync']);Storage::fake('private_local');FakeFaceProvider::reset();}private function u(string$e):User{return User::create(['name'=>'User','email'=>$e,'password'=>Hash::make('x'),'status'=>'active','account_type'=>'photographer']);}private function g(User$u,bool$admin=true):Group{$g=Group::create(['name'=>'Event','creator_id'=>$u->id,'face_recognition_enabled'=>true]);$g->members()->attach($u->id,['role'=>$admin?'admin':'member','membership_status'=>'active','access_type'=>$admin?'full_access':'partial_access']);return$g;}private function consent(Group$g,User$u,string$state='granted'):BiometricConsent{return BiometricConsent::create(['uuid'=>(string)Str::uuid(),'group_id'=>$g->id,'user_id'=>$u->id,'purpose'=>'event_photo_matching','privacy_notice_version'=>'exact-v7','state'=>$state,'granted_at'=>now(),'withdrawn_at'=>$state==='withdrawn'?now():null]);}private function asset(Group$g,User$u,string$hash='a'):MediaAsset{$key='media/originals/'.Str::uuid().'.jpg';Storage::disk('private_local')->put($key,'bytes-'.$hash);$p=Photo::create(['group_id'=>$g->id,'uploader_id'=>$u->id,'filename'=>'x.jpg','original_filename'=>'x.jpg','path'=>$key,'thumbnail_path'=>$key,'file_size'=>5,'mime_type'=>'image/jpeg']);$a=MediaAsset::create(['uuid'=>(string)Str::uuid(),'photo_id'=>$p->id,'group_id'=>$g->id,'owner_id'=>$u->id,'uploader_id'=>$u->id,'storage_disk'=>'private_local','original_object_key'=>$key,'original_filename'=>'x.jpg','mime_type'=>'image/jpeg','size_bytes'=>5,'checksum_sha256'=>hash('sha256',$hash),'state'=>'completed']);MediaVariant::create(['media_asset_id'=>$a->id,'variant_type'=>'original','storage_disk'=>'private_local','object_key'=>$key,'mime_type'=>'image/jpeg','size_bytes'=>5,'checksum_sha256'=>$a->checksum_sha256,'state'=>'ready']);return$a;}private function subject(Group$g,User$u,BiometricConsent$c,string$state='queued'):FaceSearchSubject{$key='media/temp/selfies/'.Str::uuid().'.jpg';Storage::disk('private_local')->put($key,'selfie');return FaceSearchSubject::create(['uuid'=>(string)Str::uuid(),'biometric_consent_id'=>$c->id,'group_id'=>$g->id,'user_id'=>$u->id,'storage_disk'=>'private_local','object_key'=>$key,'checksum_sha256'=>hash('sha256','selfie'),'state'=>$state,'expires_at'=>now()->addHour()]);}
 public function test_no_withdrawn_and_cross_event_consent_are_blocked():void{$u=$this->u('a@t.test');$g=$this->g($u);$other=$this->g($this->u('b@t.test'));$this->actingAs($u)->postJson(route('biometric.search',$g),['consent_uuid'=>(string)Str::uuid(),'selfie'=>UploadedFile::fake()->image('s.jpg')])->assertNotFound();foreach([$this->consent($g,$u,'withdrawn'),$this->consent($other,$other->creator)]as$c)$this->postJson(route('biometric.search',$g),['consent_uuid'=>$c->uuid,'selfie'=>UploadedFile::fake()->image('s.jpg')])->assertNotFound();}
 public function test_threshold_no_match_no_face_multiple_face_and_cleanup():void{$u=$this->u('c@t.test');$g=$this->g($u);$a=$this->asset($g,$u);foreach([['matches'=>[['external_id'=>$a->uuid,'similarity'=>94.9]],'outcome'=>null],['matches'=>[],'outcome'=>null],['matches'=>[],'outcome'=>'no_face'],['matches'=>[],'outcome'=>'multiple_faces']]as$case){config(['face.fake_matches'=>$case['matches'],'face.fake_outcome'=>$case['outcome']]);$s=$this->subject($g,$u,$this->consent($g,$u));(new SearchFaces($s->id))->handle(app(FaceRecognitionManager::class));$this->assertCount(0,$s->results);$this->assertSame($case['outcome'],$s->fresh()->outcome);Storage::disk('private_local')->assertMissing($s->object_key);}}
 public function test_above_threshold_and_duplicate_job_are_durable_once():void{$u=$this->u('d@t.test');$g=$this->g($u);$a=$this->asset($g,$u);config(['face.fake_matches'=>[['external_id'=>$a->uuid,'similarity'=>97]]]);$s=$this->subject($g,$u,$this->consent($g,$u));$job=new SearchFaces($s->id);$job->handle(app(FaceRecognitionManager::class));$job->handle(app(FaceRecognitionManager::class));$this->assertDatabaseCount('face_match_results',1);$this->assertSame('completed',$s->fresh()->state);}
 public function test_provider_failure_erases_selfie_and_logs_no_sensitive_values():void{$u=$this->u('e@t.test');$g=$this->g($u);$s=$this->subject($g,$u,$this->consent($g,$u));$key=$s->object_key;$provider=Mockery::mock(FaceProvider::class);$provider->shouldReceive('resolveCollection')->andReturn('c');$provider->shouldReceive('search')->andThrow(new RuntimeException('secret-selfie-value'));$manager=new FaceRecognitionManager($provider,app(ProtectedMediaStorage::class));Log::spy();try{(new SearchFaces($s->id))->handle($manager);}catch(RuntimeException){}Storage::disk('private_local')->assertMissing($key);$this->assertSame('failed',$s->fresh()->state);Log::shouldNotHaveReceived('error');}
 public function test_reindex_checksum_change_removes_stale_face():void{$u=$this->u('f@t.test');$g=$this->g($u);$a=$this->asset($g,$u,'v1');$m=app(FaceRecognitionManager::class);$m->index($a);$first=$a->fresh()->checksum_sha256;$a->update(['checksum_sha256'=>hash('sha256','v2')]);$m->index($a->fresh());$this->assertDatabaseCount('indexed_faces',1);$this->assertDatabaseHas('indexed_faces',['source_checksum_sha256'=>hash('sha256','v2')]);$this->assertNotSame($first,$a->fresh()->checksum_sha256);}
 public function test_my_photos_reauthorizes_and_rejection_is_durable():void{$u=$this->u('g@t.test');$g=$this->g($u,false);$a=$this->asset($g,$u);$s=$this->subject($g,$u,$this->consent($g,$u),'completed');$m=FaceMatchResult::create(['face_search_subject_id'=>$s->id,'media_asset_id'=>$a->id,'similarity'=>99,'review_state'=>'accepted']);$a->update(['state'=>'failed']);$this->actingAs($u)->getJson(route('biometric.my-photos',$s))->assertOk()->assertJsonCount(0,'photos');$this->postJson(route('biometric.reject',$m))->assertOk()->assertJson(['state'=>'rejected']);$this->assertDatabaseHas('biometric_reports',['face_match_result_id'=>$m->id,'reason'=>'not_me']);}
 public function test_manual_review_requires_event_manager():void{$owner=$this->u('h@t.test');$g=$this->g($owner);$member=$this->u('i@t.test');$g->members()->attach($member->id,['role'=>'member','membership_status'=>'active','access_type'=>'partial_access']);$a=$this->asset($g,$owner);$s=$this->subject($g,$member,$this->consent($g,$member),'completed');$m=FaceMatchResult::create(['face_search_subject_id'=>$s->id,'media_asset_id'=>$a->id,'similarity'=>99]);$this->actingAs($member)->postJson(route('biometric.review',$m),['decision'=>'confirmed'])->assertForbidden();$this->actingAs($owner)->postJson(route('biometric.review',$m),['decision'=>'confirmed'])->assertOk();$this->assertSame('confirmed',$m->fresh()->review_state);}
 public function test_minor_processing_is_blocked_and_consent_history_is_exact():void{$u=$this->u('j@t.test');$g=$this->g($u);$this->actingAs($u)->postJson(route('biometric.consent',$g),['accepted'=>true,'is_minor'=>true,'privacy_notice_version'=>'v9'])->assertForbidden();$this->postJson(route('biometric.consent',$g),['accepted'=>true,'privacy_notice_version'=>'v9'])->assertCreated();$this->assertDatabaseHas('biometric_consent_events',['purpose'=>'event_photo_matching','consent_version'=>'v9','action'=>'granted']);}
 public function test_provider_deletion_transient_retry_and_permanent_status():void{$o=ProviderDeletionOperation::create(['uuid'=>(string)Str::uuid(),'provider'=>'fake','operation'=>'collection','provider_references'=>['collection'=>'c'],'state'=>'queued']);$p=Mockery::mock(FaceProvider::class);$p->shouldReceive('deleteCollection')->once()->andThrow(new RuntimeException('transient'));$p->shouldReceive('deleteCollection')->once();$job=new ExecuteProviderDeletion($o->id);try{$job->handle($p);}catch(RuntimeException){}$this->assertSame('failed',$o->fresh()->state);$job->handle($p);$this->assertSame('completed',$o->fresh()->state);$this->assertSame(2,$o->fresh()->attempts);}
 public function test_rekognition_request_shape_uses_bytes_threshold_and_limit():void{$mock=new MockHandler();$mock->append(new Result(['FaceMatches'=>[]]));$client=new RekognitionClient(['version'=>'latest','region'=>'ap-south-1','credentials'=>['key'=>'x','secret'=>'y'],'handler'=>$mock]);(new RekognitionFaceProvider($client))->search('lenspic-event-1','not-real-biometric-data',95,100);$cmd=$mock->getLastCommand();$this->assertSame('lenspic-event-1',$cmd['CollectionId']);$this->assertSame(95.0,$cmd['FaceMatchThreshold']);$this->assertSame(100,$cmd['MaxFaces']);$this->assertArrayHasKey('Bytes',$cmd['Image']);}
 public function test_cancellation_deletes_selfie_and_is_idempotently_terminal():void{$u=$this->u('cancel@t.test');$g=$this->g($u);$s=$this->subject($g,$u,$this->consent($g,$u));$key=$s->object_key;$this->actingAs($u)->postJson(route('biometric.cancel',$s))->assertOk()->assertJson(['state'=>'cancelled','deletion_state'=>'completed']);Storage::disk('private_local')->assertMissing($key);$this->assertSame('cancelled',$s->fresh()->state);}
 public function test_complete_event_biometric_deletion_removes_subjects_and_marks_audit_complete():void{$u=$this->u('delete@t.test');$g=$this->g($u);$c=$this->consent($g,$u);$s=$this->subject($g,$u,$c);$key=$s->object_key;$response=$this->actingAs($u)->postJson(route('biometric.deletion'),['scope'=>'event','group_id'=>$g->id])->assertAccepted();$uuid=$response->json('uuid');$this->assertDatabaseHas('biometric_deletion_requests',['uuid'=>$uuid,'state'=>'completed','attempts'=>1]);$this->assertDatabaseHas('biometric_consents',['id'=>$c->id,'state'=>'deleted']);Storage::disk('private_local')->assertMissing($key);}
 public function test_search_job_exposes_concurrent_processing_lock():void{$u=$this->u('lock@t.test');$g=$this->g($u);$s=$this->subject($g,$u,$this->consent($g,$u));$middleware=(new SearchFaces($s->id))->middleware();$this->assertCount(1,$middleware);$this->assertInstanceOf(\Illuminate\Queue\Middleware\WithoutOverlapping::class,$middleware[0]);}
}
